using System;
using Godot;
using TimelapseInvoices.Scripts.Autoloads;

//实弹类
public partial class AutocannonWeapon: Weapon
{
    [Export]
    public new WeaponData Data { get; set; } = new WeaponData();

    //开火方法
    public void Fire()
    {
    }
    //换弹方法
    public void Reload()
    {

    }
    //子弹场景
    private PackedScene _bulletScene;
    //初始化方法
    public override void _Ready()
    {

        //武器类型
        Data.CurrentWeaponType = WeaponData.WeaponType.Bullet;
        //加载子弹场景
        try
        {

            _bulletScene = ResourceLoader.Load<PackedScene>(NodeController.NodeDictionary["Projectile"]);
        }
        catch (Exception ex)
        {
            GD.PrintErr($"无法加载子弹资源: {ex.Message}");
        }



    }
    //射击方法(左键)
    public override void _Input(InputEvent @event)
    {
        if (@event is InputEventMouseButton mouseButtonEvent && mouseButtonEvent.IsPressed())
        {
            if (mouseButtonEvent.ButtonIndex == MouseButton.Left)
            {
                Fire();
            }
        }
    }
    //更新方法
    public override void _Process(double delta)
    {

    }
    //fire方法   
    public void FireProjectile()
    {
        if (_bulletScene == null)
        {
            GD.PrintErr("子弹场景未加载，无法发射子弹。");
            return;
        }

        // 实例化子弹
        Projectile bullet = _bulletScene.Instantiate<Projectile>();
        if (bullet == null)
        {
            GD.PrintErr("子弹实例化失败。");
            return;
        }

        // 设置子弹位置和方向
        bullet.GlobalPosition = FirePoint.GlobalPosition;
        bullet.GlobalRotation = FirePoint.GlobalRotation;

        // 添加到发射点
        FirePoint.AddChild(bullet);

    }
}

using System;
using Godot;
using TimelapseInvoices.Scripts.Autoloads;

//实弹类
public partial class AutocannonWeapon: Weapon
{
    //子弹场景
    private PackedScene _bulletScene;

    //初始化方法
    public override void _Ready()
    {
        //武器类型
        Data.CurrentWeaponType = WeaponData.WeaponType.Bullet;
        //加载子弹场景
        try
        {
            _bulletScene = ResourceLoader.Load<PackedScene>(NodeController.NodeDictionary["Projectile"]);
        }
        catch (Exception ex)
        {
            GD.PrintErr($"无法加载子弹资源: {ex.Message}");
        }
    }

    //射击方法(左键)
    public override void _Input(InputEvent @event)
    {
        if (@event is InputEventMouseButton mouseButtonEvent && mouseButtonEvent.IsPressed())
        {
            if (mouseButtonEvent.ButtonIndex == MouseButton.Left)
            {
                Fire();
            }

            // 右键换弹
            if (mouseButtonEvent.ButtonIndex == MouseButton.Right && !_isReloading && Data.CurrentAmmo < Data.AmmoCapacity)
            {
                Reload();
            }
        }
    }

    //更新方法
    public override void _Process(double delta)
    {
        base._Process(delta); // 调用基类方法处理冷却和散布
    }

    //开火方法
    public override void Fire()
    {
        if (CanFire())
        {
            FireProjectile();
            Data.CurrentAmmo--;
            StartCooldown();
            IncreaseSpread();

            // 自动换弹
            if (Data.CurrentAmmo <= 0)
            {
                Reload();
            }
        }
    }

    //换弹方法
    public override void Reload()
    {
        if (!_isReloading && Data.CurrentAmmo < Data.AmmoCapacity)
        {
            _isReloading = true;
            _reloadTimer = Data.ReloadTime;
            GD.Print($"正在换弹，需要{Data.ReloadTime}秒");
        }
    }

    //fire方法   
    public void FireProjectile()
    {
        if (_bulletScene == null)
        {
            GD.PrintErr("子弹场景未加载，无法发射子弹。");
            return;
        }

        // 实例化子弹
        Projectile bullet = _bulletScene.Instantiate<Projectile>();
        if (bullet == null)
        {
            GD.PrintErr("子弹实例化失败。");
            return;
        }

        // 设置子弹位置和方向（加入散布效果）
        bullet.GlobalPosition = FirePoint.GlobalPosition;
        bullet.GlobalRotation = FirePoint.GlobalRotation + GetSpreadRotation();

        // 添加到发射点
        FirePoint.AddChild(bullet);

        // 可以添加发射音效
        // if (_fireSound != null) _fireSound.Play();
    }
}

using Godot;
using System;
using TimelapseInvoices.Scripts.Autoloads;

public partial class Weapon : Node2D
{
    // 武器数据
    [Export]
    public WeaponData Data { get; set; } = new WeaponData();

    // 计时器节点，用于处理换弹逻辑
    public Timer ReloadTimer;

    // 开火冷却跟踪
    private float _fireInterval => Data.FireRate; // 计算射击间隔时间
    private bool _isReloading = false;

    // 发射点
    public Node2D FirePoint;

    // 散布相关
    private float _currentSpreadAngle = 0f; // 当前散布角度
    private float _lastShotTime = 0f; // 上次射击时间，用于计算散布恢复
    private readonly float _degToRad = (float)Math.PI / 180f; // 度转弧度的常量

    // 预加载的子弹场景
    private PackedScene _bulletScene;

    // 准备完成
    public override void _Ready()
    {
        // 初始化换弹计时器

    }

    // 子弹
    Projectile _bulletPrefab;

    // 输入处理
    public override void _Input(InputEvent @event)
    {

    }

}

